-- ForgeOps AI Phase 1: operational persistence. Run before seed/001_fictional_demo.sql.
create table if not exists suppliers (id text primary key, name text not null, active boolean not null default true, created_at timestamptz not null default now());
create table if not exists programmes (id text primary key, name text not null, owner text not null, description text, target_date date not null, status text not null check (status in ('on_track','at_risk','recovering','complete')), priority text not null check (priority in ('high','medium')), completion_percent int not null check (completion_percent between 0 and 100), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists components (code text primary key, name text not null, supplier_id text not null references suppliers(id), lead_time_days integer not null check(lead_time_days >= 0), on_hand numeric not null default 0 check(on_hand >= 0), reorder_point numeric not null default 0 check(reorder_point >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists bills_of_materials (id text primary key, programme_id text not null references programmes(id) on delete cascade, revision text not null, status text not null default 'active', unique(programme_id, revision));
create table if not exists bom_items (id text primary key, bom_id text not null references bills_of_materials(id) on delete cascade, programme_id text not null references programmes(id) on delete cascade, component_code text not null references components(code), required_quantity numeric not null check(required_quantity > 0), assembly_date date not null, unique(bom_id, component_code));
create table if not exists milestones (id text primary key, programme_id text not null references programmes(id) on delete cascade, name text not null, owner text not null, due_date date not null, duration_days integer not null default 1 check(duration_days > 0), status text not null check(status in ('open','complete')), material_component_code text references components(code), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists milestone_dependencies (milestone_id text not null references milestones(id) on delete cascade, depends_on_id text not null references milestones(id) on delete restrict, primary key(milestone_id, depends_on_id), check(milestone_id <> depends_on_id));
create table if not exists purchase_orders (id text primary key, supplier_id text not null references suppliers(id), status text not null check(status in ('open','received','cancelled')), committed_date date, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists purchase_order_items (id text primary key, po_id text not null references purchase_orders(id) on delete cascade, component_code text not null references components(code), quantity numeric not null check(quantity > 0), unique(po_id, component_code));
create table if not exists work_centers (id text primary key, name text not null, weekly_hours numeric not null check(weekly_hours >= 0), planned_hours numeric not null check(planned_hours >= 0), programme_id text not null references programmes(id));
create table if not exists regulatory_documents (id text primary key, programme_id text not null references programmes(id), title text not null, owner text not null, approval_due date not null, status text not null check(status in ('draft','approved')), created_at timestamptz not null default now());
create index if not exists idx_bom_items_programme on bom_items(programme_id); create index if not exists idx_milestones_programme_due on milestones(programme_id, due_date); create index if not exists idx_po_items_component on purchase_order_items(component_code);
-- RLS policies must be added together with Supabase Auth/organisation tenancy. Service-role access is server-only.
